/* Loop state for one walk over portConfigTable's rows. */
struct portConfigTable_loop {
    table_rowset_t *rows;
    size_t          next;
};

/*
 * Data context for a matched row of portConfigTable.
 *
 * It carries no row data on purpose. net-snmp's table iterator hands the
 * same data context pointer to every request that matched the same row and
 * then releases it once per request, so a per-row allocation here would be a
 * double free the moment a manager set two columns of one row in a single
 * PDU. The address of this object only means "the row exists"; the instance
 * itself is recovered from the request's index varbinds with
 * table_instance_from_indexes() (see include/table_oid.h), which is also
 * what keeps MODE_SET_RESERVE2 and later working -- only MODE_SET_RESERVE1
 * walks the rows.
 */
static char portConfigTable_row_present;

/* Last reported count of skipped (malformed) cell keys, see below. */
static size_t portConfigTable_last_skipped;

static Netsnmp_Node_Handler        handle_portConfigTable;
static Netsnmp_First_Data_Point    portConfigTable_get_first_data_point;
static Netsnmp_Next_Data_Point     portConfigTable_get_next_data_point;
static Netsnmp_Free_Loop_Context   portConfigTable_free_loop_context;

/*
 * The (environment, column) pairs a row of portConfigTable can appear under. Filled at
 * call time rather than statically initialised because config_env/cache_env
 * are runtime handles.
 */
static void
portConfigTable_column_refs(table_column_ref_t refs[portConfigTable_NCOLUMNS])
{
    refs[0].env = TABLE_ENV_portDescr;
    refs[0].column = "portDescr";
    refs[1].env = TABLE_ENV_portAdminStatus;
    refs[1].column = "portAdminStatus";
    refs[2].env = TABLE_ENV_portAlarmThresholdMilliC;
    refs[2].column = "portAlarmThresholdMilliC";
}

static netsnmp_variable_list *
portConfigTable_get_first_data_point(void **loop_context, void **data_context,
                          netsnmp_variable_list *put_index_data,
                          netsnmp_iterator_info *iinfo)
{
    table_column_ref_t refs[portConfigTable_NCOLUMNS];
    struct portConfigTable_loop *loop;
    table_rowset_t *rows = NULL;
    storage_rc_t rc;

    /*
     * With NETSNMP_ITERATOR_FLAG_SORTED the iterator passes a hint of its own
     * in *loop_context. This function ignores it and installs its own loop
     * state -- but it must install something on every path, including the
     * failure paths below: whatever *loop_context holds at the end of the
     * iteration is handed to portConfigTable_free_loop_context().
     */
    *loop_context = NULL;

    portConfigTable_column_refs(refs);

    rc = table_rowset_load(refs, portConfigTable_NCOLUMNS, &rows);
    if (rc != STORAGE_OK) {
        snmp_log(LOG_ERR, "portConfigTable: row enumeration failed: %s\n",
                  storage_strerror(rc));
        return NULL;
    }
    /*
     * Rows are enumerated once per request, so an unconditional warning here
     * would repeat for every varbind of every walk. Report only when the
     * count changes, which still surfaces a writer that starts (or stops)
     * producing malformed keys without burying the log.
     */
    if (table_rowset_skipped(rows) != portConfigTable_last_skipped) {
        portConfigTable_last_skipped = table_rowset_skipped(rows);
        if (portConfigTable_last_skipped > 0) {
            snmp_log(LOG_WARNING,
                      "portConfigTable: ignoring %lu cell key(s) whose row instance is not "
                      "canonical dotted decimal\n",
                      (unsigned long)portConfigTable_last_skipped);
        }
    }

    loop = calloc(1, sizeof(*loop));
    if (loop == NULL) {
        table_rowset_free(rows);
        snmp_log(LOG_ERR, "portConfigTable: out of memory allocating loop context\n");
        return NULL;
    }
    loop->rows = rows;
    loop->next = 0;
    *loop_context = loop;

    return portConfigTable_get_next_data_point(loop_context, data_context,
                                    put_index_data, iinfo);
}

static netsnmp_variable_list *
portConfigTable_get_next_data_point(void **loop_context, void **data_context,
                         netsnmp_variable_list *put_index_data,
                         netsnmp_iterator_info *iinfo)
{
    struct portConfigTable_loop *loop = (struct portConfigTable_loop *)*loop_context;

    (void)iinfo;

    if (loop == NULL) {
        return NULL;
    }

    while (loop->next < table_rowset_count(loop->rows)) {
        const table_instance_t *inst = table_rowset_at(loop->rows, loop->next++);

        /*
         * put_index_data carries this table's index syntax, so filling it is
         * also the validation step: a key whose instance does not decode into
         * exactly these indexes is not a row of this table and is skipped
         * rather than reported as one.
         */
        if (table_instance_to_indexes(inst, put_index_data) != 0) {
            char rejected[STORAGE_KEY_MAX + 1];

            if (table_instance_format(inst, rejected, sizeof(rejected))
                    != STORAGE_OK) {
                rejected[0] = '\0';
            }
            snmp_log(LOG_WARNING,
                      "portConfigTable: instance '%s' does not match the table's index "
                      "syntax, skipping the row\n", rejected);
            continue;
        }

        *data_context = &portConfigTable_row_present;

        return put_index_data;
    }

    return NULL;
}

static void
portConfigTable_free_loop_context(void *context, netsnmp_iterator_info *iinfo)
{
    struct portConfigTable_loop *loop = (struct portConfigTable_loop *)context;

    (void)iinfo;

    if (loop == NULL) {
        return;
    }
    table_rowset_free(loop->rows);
    free(loop);
}

/** Registers the portConfigTable table with the master agent. */
static void
init_table_portConfigTable(void)
{
    static const oid portConfigTable_oid[] = { 1,3,6,1,4,1,99999,1,5 };
    netsnmp_handler_registration *reg;
    netsnmp_table_registration_info *table_info;
    netsnmp_iterator_info *iinfo;

    DEBUGMSGTL(("demo_config_table", "Registering table portConfigTable\n"));

    reg = netsnmp_create_handler_registration(
              "portConfigTable", handle_portConfigTable, portConfigTable_oid, OID_LENGTH(portConfigTable_oid),
              HANDLER_CAN_RWRITE);
    if (reg == NULL) {
        snmp_log(LOG_ERR, "portConfigTable: handler registration allocation failed\n");
        return;
    }

    table_info = SNMP_MALLOC_TYPEDEF(netsnmp_table_registration_info);
    iinfo = SNMP_MALLOC_TYPEDEF(netsnmp_iterator_info);
    if (table_info == NULL || iinfo == NULL) {
        snmp_log(LOG_ERR, "portConfigTable: out of memory registering the table\n");
        SNMP_FREE(table_info);
        SNMP_FREE(iinfo);
        netsnmp_handler_registration_free(reg);
        return;
    }

    netsnmp_table_helper_add_indexes(table_info,
                                      ASN_UNSIGNED, /* index: portIndex */
                                      0);
    table_info->min_column = COLUMN_PORTDESCR;
    table_info->max_column = COLUMN_PORTALARMTHRESHOLDMILLIC;

    iinfo->get_first_data_point     = portConfigTable_get_first_data_point;
    iinfo->get_next_data_point      = portConfigTable_get_next_data_point;
    iinfo->free_loop_context_at_end = portConfigTable_free_loop_context;
    /* No free_data_context: a matched row's context is the static sentinel
     * above, not an allocation (see its comment). */
    iinfo->table_reginfo            = table_info;
    /* table_rowset_load() returns rows already in OID order, which lets the
     * iterator stop a GETNEXT at the first row past the requested one. */
    iinfo->flags                   |= NETSNMP_ITERATOR_FLAG_SORTED;

    if (netsnmp_register_table_iterator(reg, iinfo) != SNMPERR_SUCCESS) {
        snmp_log(LOG_ERR, "portConfigTable: netsnmp_register_table_iterator failed\n");
    }
}

/** Handles requests for the portConfigTable table. */
static int
handle_portConfigTable(netsnmp_mib_handler *handler,
          netsnmp_handler_registration *reginfo,
          netsnmp_agent_request_info *reqinfo,
          netsnmp_request_info *requests)
{
    netsnmp_request_info *request;

    (void)handler;
    (void)reginfo;

    switch (reqinfo->mode) {

    case MODE_GET:
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_table_request_info *table_info =
                netsnmp_extract_table_info(request);
            table_instance_t row;
            const table_instance_t *inst = &row;
            char key[STORAGE_KEY_MAX + 1];

            if (table_info == NULL) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }
            if (netsnmp_extract_iterator_context(request) == NULL) {
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHINSTANCE);
                continue;
            }
            if (table_instance_from_indexes(table_info, &row) != 0) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }

            switch (table_info->colnum) {
            case COLUMN_PORTDESCR:
                {
                    unsigned char buf[64];
                    size_t len = sizeof(buf);
                    storage_rc_t rc;

                    if (table_cell_key("portDescr", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_bytes(TABLE_ENV_portDescr, key, buf, &len);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        /* A row can exist while one of its cells does not;
                         * report the hole rather than inventing a value. */
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_bytes failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_value(request->requestvb, ASN_OCTET_STR,
                                              buf, len);
                }
                break;

            case COLUMN_PORTADMINSTATUS:
                {
                    int32_t val;
                    storage_rc_t rc;

                    if (table_cell_key("portAdminStatus", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_int(TABLE_ENV_portAdminStatus, key, &val);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_int failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_integer(request->requestvb, ASN_INTEGER,
                                                (long)val);
                }
                break;

            case COLUMN_PORTALARMTHRESHOLDMILLIC:
                {
                    int32_t val;
                    storage_rc_t rc;

                    if (table_cell_key("portAlarmThresholdMilliC", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_int(TABLE_ENV_portAlarmThresholdMilliC, key, &val);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_NOSUCHINSTANCE);
                        break;
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage_get_int failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    snmp_set_var_typed_integer(request->requestvb, ASN_INTEGER,
                                                (long)val);
                }
                break;

            default:
                netsnmp_set_request_error(reqinfo, request, SNMP_NOSUCHOBJECT);
                break;
            }
        }
        break;

    /*
     * SET REQUEST -- full net-snmp four phase state machine, per cell.
     * http://www.net-snmp.org/tutorial-5/toolkit/mib_module/set-actions.jpg
     */
    case MODE_SET_RESERVE1:
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_table_request_info *table_info =
                netsnmp_extract_table_info(request);

            if (table_info == NULL) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }
            if (netsnmp_extract_iterator_context(request) == NULL) {
                /*
                 * No such row. This table has no RowStatus column, so a
                 * manager cannot bring one into existence (docs/design.md
                 * 3.2): rows are provisioned at bootstrap or written by the
                 * telemetry application.
                 */
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_NOCREATION);
                continue;
            }

            switch (table_info->colnum) {
            case COLUMN_PORTDESCR:
                {
                    int ret = netsnmp_check_vb_type(request->requestvb,
                                                     ASN_OCTET_STR);
                    size_t vlen = request->requestvb->val_len;
                    int len_ok = 0;

                    if (ret != SNMP_ERR_NOERROR) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGTYPE);
                        break;
                    }
                    /*
                     * A SIZE clause lists alternatives, so a length is legal
                     * when it falls inside ANY of them. Rejecting per range
                     * instead would refuse a length another alternative
                     * allows -- SIZE (0 | 4 | 16) would accept nothing.
                     */
                    /* No lower bound to test: val_len is unsigned, and
                     * comparing it against 0 is a -Wtype-limits warning. */
                    if (vlen <= (size_t)(63)) {
                        len_ok = 1;
                    }
                    if (!len_ok) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGLENGTH);
                        break;
                    }
                }
                break;

            case COLUMN_PORTADMINSTATUS:
                {
                    int ret = netsnmp_check_vb_type(request->requestvb, ASN_INTEGER);
                    long v;

                    if (ret != SNMP_ERR_NOERROR) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGTYPE);
                        break;
                    }
                    v = *request->requestvb->val.integer;
                    switch (v) {
                    case 1:
                    case 2:
                    case 3:
                        break;
                    default:
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGVALUE);
                    }
                }
                break;

            case COLUMN_PORTALARMTHRESHOLDMILLIC:
                {
                    int ret = netsnmp_check_vb_type(request->requestvb, ASN_INTEGER);
                    long v;
                    int in_range = 0;

                    if (ret != SNMP_ERR_NOERROR) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGTYPE);
                        break;
                    }
                    v = *request->requestvb->val.integer;
                    /* Alternatives, as for SIZE above: in ANY range is legal. */
                    if (v >= (-40000) && v <= (125000)) {
                        in_range = 1;
                    }
                    if (!in_range) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_WRONGVALUE);
                        break;
                    }
                }
                break;

            default:
                netsnmp_set_request_error(reqinfo, request,
                                           SNMP_ERR_NOTWRITABLE);
                break;
            }
        }
        break;

    case MODE_SET_RESERVE2:
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_table_request_info *table_info =
                netsnmp_extract_table_info(request);
            table_instance_t row;
            const table_instance_t *inst = &row;

            if (table_info == NULL ||
                netsnmp_extract_iterator_context(request) == NULL ||
                table_instance_from_indexes(table_info, &row) != 0) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }

            switch (table_info->colnum) {
            case COLUMN_PORTDESCR:
                {
                    struct undo_portDescr *prev = calloc(1, sizeof(*prev));
                    storage_rc_t rc;

                    if (prev == NULL) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    }
                    if (table_cell_key("portDescr", inst, prev->key,
                                        sizeof(prev->key)) != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    prev->len = sizeof(prev->data);
                    rc = storage_get_bytes(TABLE_ENV_portDescr, prev->key,
                                            prev->data, &prev->len);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        prev->existed = 0;
                        prev->len = 0;
                    } else if (rc != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    } else {
                        prev->existed = 1;
                    }
                    netsnmp_request_add_list_data(request,
                        netsnmp_create_data_list("undo_portDescr", prev, free));
                }
                break;

            case COLUMN_PORTADMINSTATUS:
                {
                    struct undo_portAdminStatus *prev = calloc(1, sizeof(*prev));
                    storage_rc_t rc;

                    if (prev == NULL) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    }
                    if (table_cell_key("portAdminStatus", inst, prev->key,
                                        sizeof(prev->key)) != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_int(TABLE_ENV_portAdminStatus, prev->key, &prev->value);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        prev->existed = 0;
                    } else if (rc != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    } else {
                        prev->existed = 1;
                    }
                    netsnmp_request_add_list_data(request,
                        netsnmp_create_data_list("undo_portAdminStatus", prev, free));
                }
                break;

            case COLUMN_PORTALARMTHRESHOLDMILLIC:
                {
                    struct undo_portAlarmThresholdMilliC *prev = calloc(1, sizeof(*prev));
                    storage_rc_t rc;

                    if (prev == NULL) {
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    }
                    if (table_cell_key("portAlarmThresholdMilliC", inst, prev->key,
                                        sizeof(prev->key)) != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_get_int(TABLE_ENV_portAlarmThresholdMilliC, prev->key, &prev->value);
                    if (rc == STORAGE_ERR_NOTFOUND) {
                        prev->existed = 0;
                    } else if (rc != STORAGE_OK) {
                        free(prev);
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_RESOURCEUNAVAILABLE);
                        break;
                    } else {
                        prev->existed = 1;
                    }
                    netsnmp_request_add_list_data(request,
                        netsnmp_create_data_list("undo_portAlarmThresholdMilliC", prev, free));
                }
                break;

            default:
                break;
            }
        }
        break;

    case MODE_SET_FREE:
        /* RESERVE1/RESERVE2 failed somewhere; release any stash taken. */
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_request_remove_list_data(request, "undo_portDescr");
            netsnmp_request_remove_list_data(request, "undo_portAdminStatus");
            netsnmp_request_remove_list_data(request, "undo_portAlarmThresholdMilliC");
        }
        break;

    case MODE_SET_ACTION:
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_table_request_info *table_info =
                netsnmp_extract_table_info(request);
            table_instance_t row;
            const table_instance_t *inst = &row;
            char key[STORAGE_KEY_MAX + 1];

            if (table_info == NULL ||
                netsnmp_extract_iterator_context(request) == NULL ||
                table_instance_from_indexes(table_info, &row) != 0) {
                netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                continue;
            }

            switch (table_info->colnum) {
            case COLUMN_PORTDESCR:
                {
                    storage_rc_t rc;

                    if (table_cell_key("portDescr", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_set_bytes(TABLE_ENV_portDescr, key,
                                            request->requestvb->val.string,
                                            request->requestvb->val_len);
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage write failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_COMMITFAILED);
                    }
                }
                break;

            case COLUMN_PORTADMINSTATUS:
                {
                    storage_rc_t rc;

                    if (table_cell_key("portAdminStatus", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_set_int(TABLE_ENV_portAdminStatus, key,
                                          (int32_t)*request->requestvb->val.integer);
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage write failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_COMMITFAILED);
                    }
                }
                break;

            case COLUMN_PORTALARMTHRESHOLDMILLIC:
                {
                    storage_rc_t rc;

                    if (table_cell_key("portAlarmThresholdMilliC", inst, key, sizeof(key)) != STORAGE_OK) {
                        netsnmp_set_request_error(reqinfo, request, SNMP_ERR_GENERR);
                        break;
                    }
                    rc = storage_set_int(TABLE_ENV_portAlarmThresholdMilliC, key,
                                          (int32_t)*request->requestvb->val.integer);
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: storage write failed: %s\n",
                                  key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_COMMITFAILED);
                    }
                }
                break;

            default:
                break;
            }
        }
        break;

    case MODE_SET_COMMIT:
        /* Success: the stashed previous values are no longer needed. */
        for (request = requests; request != NULL; request = request->next) {
            netsnmp_request_remove_list_data(request, "undo_portDescr");
            netsnmp_request_remove_list_data(request, "undo_portAdminStatus");
            netsnmp_request_remove_list_data(request, "undo_portAlarmThresholdMilliC");
        }
        break;

    case MODE_SET_UNDO:
        for (request = requests; request != NULL; request = request->next) {
            {
                struct undo_portDescr *prev = (struct undo_portDescr *)
                    netsnmp_request_get_list_data(request, "undo_portDescr");

                if (prev != NULL) {
                    storage_rc_t rc;

                    if (prev->existed) {
                        rc = storage_set_bytes(TABLE_ENV_portDescr, prev->key,
                                                prev->data, prev->len);
                    } else {
                        /* The cell did not exist before this SET, so undoing
                         * means removing it again, not zeroing it. */
                        rc = storage_delete(TABLE_ENV_portDescr, prev->key);
                        if (rc == STORAGE_ERR_NOTFOUND) {
                            rc = STORAGE_OK;
                        }
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: UNDO failed: %s\n",
                                  prev->key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_UNDOFAILED);
                    }
                    netsnmp_request_remove_list_data(request, "undo_portDescr");
                }
            }
            {
                struct undo_portAdminStatus *prev = (struct undo_portAdminStatus *)
                    netsnmp_request_get_list_data(request, "undo_portAdminStatus");

                if (prev != NULL) {
                    storage_rc_t rc;

                    if (prev->existed) {
                        rc = storage_set_int(TABLE_ENV_portAdminStatus, prev->key, prev->value);
                    } else {
                        /* The cell did not exist before this SET, so undoing
                         * means removing it again, not zeroing it. */
                        rc = storage_delete(TABLE_ENV_portAdminStatus, prev->key);
                        if (rc == STORAGE_ERR_NOTFOUND) {
                            rc = STORAGE_OK;
                        }
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: UNDO failed: %s\n",
                                  prev->key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_UNDOFAILED);
                    }
                    netsnmp_request_remove_list_data(request, "undo_portAdminStatus");
                }
            }
            {
                struct undo_portAlarmThresholdMilliC *prev = (struct undo_portAlarmThresholdMilliC *)
                    netsnmp_request_get_list_data(request, "undo_portAlarmThresholdMilliC");

                if (prev != NULL) {
                    storage_rc_t rc;

                    if (prev->existed) {
                        rc = storage_set_int(TABLE_ENV_portAlarmThresholdMilliC, prev->key, prev->value);
                    } else {
                        /* The cell did not exist before this SET, so undoing
                         * means removing it again, not zeroing it. */
                        rc = storage_delete(TABLE_ENV_portAlarmThresholdMilliC, prev->key);
                        if (rc == STORAGE_ERR_NOTFOUND) {
                            rc = STORAGE_OK;
                        }
                    }
                    if (rc != STORAGE_OK) {
                        snmp_log(LOG_ERR, "%s: UNDO failed: %s\n",
                                  prev->key, storage_strerror(rc));
                        netsnmp_set_request_error(reqinfo, request,
                                                   SNMP_ERR_UNDOFAILED);
                    }
                    netsnmp_request_remove_list_data(request, "undo_portAlarmThresholdMilliC");
                }
            }
        }
        break;

    default:
        snmp_log(LOG_ERR, "unknown mode (%d) in handle_portConfigTable\n", reqinfo->mode);
        return SNMP_ERR_GENERR;
    }

    return SNMP_ERR_NOERROR;
}

/** Registers every demo_config_table table with the master agent. */
void
init_demo_config_table(void)
{
    DEBUGMSGTL(("demo_config_table", "Initializing\n"));

    init_table_portConfigTable();
}
